import{_ as o,o as a,c as t,a5 as i}from"./chunks/framework.BYXPg_yw.js";const u=JSON.parse('{"title":"로봇을 인터넷에 연결하기","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/robot-internet.md","filePath":"ko/manual/operation/robot-internet.md","lastUpdated":1793350928000}'),c={name:"ko/manual/operation/robot-internet.md"};function d(r,e,n,l,s,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="로봇을-인터넷에-연결하기" tabindex="-1">로봇을 인터넷에 연결하기 <a class="header-anchor" href="#로봇을-인터넷에-연결하기" aria-label="Permalink to &quot;로봇을 인터넷에 연결하기&quot;">​</a></h1><p>원격 점검과 원격 앱 연결은 로봇이 직접 인터넷에 닿아야 합니다. 로봇 공유기가 현장 와이파이에 손님으로 붙어(무선 WAN, WISP라고도 합니다) 그 인터넷을 로봇과 나눠 씁니다. 로봇에 USIM이 들어 있으면 이미 인터넷에 붙어 있으니 이 페이지는 건너뛰세요.</p><h2 id="before" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#before" aria-label="Permalink to &quot;시작하기 전에 {#before}&quot;">​</a></h2><ul><li>인터넷이 되는 현장 와이파이의 이름과 비밀번호</li><li>로봇 와이파이(<code>RBQ_{XX}</code>)에 붙은 휴대폰·태블릿·PC</li><li>공유기 관리자 비밀번호. 모르면 지원 담당에게 문의하세요.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>웹 로그인 화면이 뜨거나 기기(MAC) 등록이 필요한 망에서는 안 됩니다. 이럴 때는 휴대폰 핫스팟을 켜고, 같은 방법으로 핫스팟을 현장 와이파이로 골라 붙이세요.</p></div></div><h2 id="open" tabindex="-1">1단계: 공유기 설정 열기 <a class="header-anchor" href="#open" aria-label="Permalink to &quot;1단계: 공유기 설정 열기 {#open}&quot;">​</a></h2><p>로봇 와이파이에 붙은 기기의 브라우저에서 <code>http://192.168.0.1</code>을 열고 로그인합니다.</p><h2 id="wisp" tabindex="-1">2단계: 무선 WAN 켜기 <a class="header-anchor" href="#wisp" aria-label="Permalink to &quot;2단계: 무선 WAN 켜기 {#wisp}&quot;">​</a></h2><ol><li><code>무선랜 관리</code> › <code>무선 확장 설정</code>으로 갑니다.</li><li><strong>2.4GHz</strong>에서 <code>무선 WAN</code>을 고릅니다. <code>브리지</code>는 고르지 마세요 — 로봇 주소가 바뀝니다.</li><li>네트워크 이름 옆 검색 버튼을 눌러 현장 와이파이를 고르고, 비밀번호를 넣고 <code>적용</code>을 누릅니다.</li><li>붙으면 2.4GHz 칸에 <code>무선 WAN 연결됨</code>과 신호 세기가 표시됩니다.</li></ol><p><strong>5GHz</strong>는 <code>중단</code>으로 둡니다. 로봇 자체 와이파이가 5GHz면, 여기서 무선 WAN을 켤 때 바꾸는 동안 컨트롤러 연결이 끊길 수 있습니다.</p><h2 id="dynamic-ip" tabindex="-1">3단계: 동적 IP 쓰기 <a class="header-anchor" href="#dynamic-ip" aria-label="Permalink to &quot;3단계: 동적 IP 쓰기 {#dynamic-ip}&quot;">​</a></h2><p><code>네트워크 관리</code> › <code>인터넷 설정 정보</code>로 갑니다. <code>고정 IP 방식</code>이 골라져 있으면 이전 현장의 주소가 남아 있는 것이라 인터넷이 안 됩니다. <code>동적 IP 방식</code>을 고르고 <code>적용</code>을 누릅니다.</p><h2 id="check" tabindex="-1">4단계: 확인 <a class="header-anchor" href="#check" aria-label="Permalink to &quot;4단계: 확인 {#check}&quot;">​</a></h2><p>앱 <strong>정비</strong> › <code>로봇 점검</code>을 열고 맨 아래 <code>원격 점검</code>으로 내려갑니다. 로봇이 인터넷에 닿으면 인터넷 경고가 사라지고 켜기 버튼이 눌립니다. 경고가 그대로면 위 단계를 다시 확인하거나 지원 담당에게 문의하세요.</p>',14)])])}const b=o(c,[["render",d]]);export{u as __pageData,b as default};
